    def clamp(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_pos(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            for k in ("pos", "position", "loc", "location", "xy", "coord", "coords"):
                v = obj.get(k)
                if isinstance(v, (list, tuple)) and len(v) >= 2:
                    return [v[0], v[1]]
            x = obj.get("x")
            y = obj.get("y")
            if x is not None and y is not None:
                return [x, y]
        elif isinstance(obj, (list, tuple)) and len(obj) >= 2 and isinstance(obj[0], (int, float)) and isinstance(obj[1], (int, float)):
            return [obj[0], obj[1]]
        return None

    def extract_positions(value):
        res = []
        if value is None:
            return res
        if isinstance(value, dict):
            for k in ("positions", "cells", "targets", "resources", "enemies", "agents", "players", "objects", "items"):
                if k in value:
                    res.extend(extract_positions(value.get(k)))
            p = get_pos(value)
            if p is not None:
                res.append(p)
        elif isinstance(value, (list, tuple)):
            for v in value:
                p = get_pos(v)
                if p is not None:
                    res.append(p)
                elif isinstance(v, (list, tuple)):
                    res.extend(extract_positions(v))
                elif isinstance(v, dict):
                    res.extend(extract_positions(v))
        return res

    def infer_self_pos(obs):
        for k in ("agent_pos", "self_pos", "player_pos", "position", "pos", "loc", "location"):
            p = get_pos(obs.get(k)) if isinstance(obs, dict) else None
            if p is not None:
                return p
        me = None
        if isinstance(obs, dict):
            for k in ("agent", "self", "player", "me"):
