                    for a in arr:
                        if isinstance(a, dict) and a.get("self"):
                            p = get_pos(a)
                            if p is not None:
                                return p
                            idx = a.get("idx", a.get("id"))
                            if idx == 0:
                                p = get_pos(a)
                                if p is not None:
                                    return p
        return None

    def grid_blocked(grid, x, y):
        if grid is None:
            return False
        if y < 0 or y >= len(grid):
            return True
        row = grid[y]
        if x < 0 or x >= len(row):
            return True
        cell = row[x]
        return cell in (1, "#", "X", "x", True, "wall", "W")

    def bounds_from_grid(grid):
        if isinstance(grid, (list, tuple)) and grid:
            h = len(grid)
            w = 0
            for row in grid:
                if isinstance(row, (list, tuple)) and len(row) > w:
                    w = len(row)
            return w, h
        return None, None

