        resources.extend(extract_positions(obs.get(k)))
    enemies = []
    for k in ("enemies", "enemy_positions", "opponents", "opponent_positions", "threats"):
        enemies.extend(extract_positions(obs.get(k)))
    territories = []
    for k in ("territory_targets", "frontier", "unclaimed", "neutral", "capture_points", "control_points"):
        territories.extend(extract_positions(obs.get(k)))
    goals = []
    for k in ("goals", "targets", "target", "objective", "objectives"):
        goals.extend(extract_positions(obs.get(k)))

    # Scenario inference
    mode = obs.get("mode") if isinstance(obs, dict) else None
    if not mode:
