                    # Usually evade if too close; if far, don't overreact
                    score += d * 8
                if goals:
                    d = min(manhattan([nx, ny], g) for g in goals)
                    score -= d * 2
            elif mode == "territory_control":
                if territories:
                    d = min(manhattan([nx, ny], t) for t in territories)
                    score -= d * 8
                if enemies:
                    d = min(manhattan([nx, ny], e) for e in enemies)
                    score += d * 2
            else:
                if goals:
                    d = min(manhattan([nx, ny], g) for g in goals)
                    score -= d * 5
                if resources:
                    d = min(manhattan([nx, ny], t) for t in resources)
                    score -= d * 3
                if enemies:
                    d = min(manhattan([nx, ny], e) for e in enemies)
                    score += d * 1

            # Small preference for movement over standing still when tied
            if dx != 0 or dy != 0:
                score += 0.1

            # Mild center-seeking if no targets
            if w is not None and h is not None and not resources and not enemies and not territories and not goals:
                cx, cy = (w - 1) / 2.0, (h - 1) / 2.0
                score -= abs(nx - cx) + abs(ny - cy)

            candidates.append((score, dx, dy))

    if not candidates:
        return [0, 0]

    candidates.sort(key=lambda t: (-t[0], abs(t[1]) + abs(t[2]), t[1], t[2]))
    best = candidates[0]
    return [clamp(best[1]), clamp(best[2])]

